const rcLinhaAguarda=(n,num,sub)=>`<a href="#senhas" onclick="event.preventDefault();rcIrSenha('${esc(num)}')" style="display:block;color:inherit;text-decoration:none"><b>${esc(n||'Senha '+num)}</b><small style="display:block;color:var(--fg2)">${sub}</small></a>`;

/* Novo atendimento concluído entra na fila do setor */
function rcAposAtendimento(p,procs,pg){rc();let s=RC.senhas.find(x=>x.pac===p.n&&RC_ABERTAS.includes(x.st));
 if(!s){const r=rcGerarSenha({pac:p.n,cpf:p.cpf,orig:'balcão'});if(r.erro)return;s=r.senha}
 s.st='finalizada';s.hFim=hhmm(new Date());RC.chamadas=RC.chamadas.filter(c=>c.sid!==s.id||c.painel!=='rec');rcTiraFila(s.num);const novos=rcEncaminhar(s,procs,{guia:true,ag:s.ag||null});
 if(pg&&procs.length){const g=rcGuiaCriar(s,procs,pg.conv,pg.desc,0);novos.forEach(e=>e.guia=g.num);if(g.pagar>0)rcPagar(g,pg.forma,g.pagar)}rcPublica()}

/* ---------- Atendimentos nos setores ---------- */
const rcAtDa=id=>RC.at.find(e=>e.id===id);
function rcChamarConsultorio(a,local){rc();const e=RC.at.find(x=>x.ag===a&&x.st!=='fim');if(e){e.st='atendimento';e.local=local;e.hIni=hhmm(new Date());e.prof=(PROF(a.prof)||{}).n||'';rcPainelAdd(e,local,e.setor)}else rcPainelAdd({id:0,num:'Paciente',pac:a.pac,cpf:'',peso:'NOR',unid:RC.unid},local,'consult');rcPublica()}
const rcSetoresVis=()=>{const l=RC.cfg.setores.filter(s=>(s.perfis||[]).includes(PERFIL));return l.length?l:RC.cfg.setores};
/* Primeira sala livre do setor */
function rcAtLocalDe(e){if(e.local)return e.local;const l=(rcSetor(e.setor)||{locais:['']}).locais;return l.find(x=>!RC.at.some(o=>o!==e&&o.local===x&&o.unid===e.unid&&o.st==='atendimento'))||l[0]||''}
/* Chamar passa direto para Em atendimento; de lá, chama de novo */
function rcAtChamar(id){const e=rcAtDa(id);if(!e)return;const rep=e.st==='atendimento',set=rcSetor(e.setor);if(!rep&&e.st!=='espera'){toast('Só quem está em espera pode ser chamado','warn');return}
 if(set&&set.tipos.length&&!set.tipos.includes(e.tipo)){toast(`${set.n} não atende este tipo de senha`,'warn');return}
 const l=rcAtLocalDe(e);e.local=l;rcTiraFila(e.num);rcPainelAdd(e,l,e.setor);if(rep)rcMudou();else rcAtIniciar(id);toast(`${e.pac?e.pac.split(' ')[0]:'Senha '+e.num}${rep?' chamado de novo':' chamado'}: ${l}`)}
function rcAtIniciar(id){const e=rcAtDa(id);if(!e)return;e.local=rcAtLocalDe(e);e.st='atendimento';e.hIni=hhmm(new Date());e.op=rcResp();e.prof=e.ag?((PROF(e.ag.prof)||{}).n||''):nomePerfil(PERFIL);if(e.ag)e.ag.sit='em atendimento';rcHist(e,'procedimento','Em atendimento',`${rcProcsTxt(e.procs)} · ${e.local}`,e.prof);RC.atTab='atendimento';rcMudou()}
function rcAtFinalizar(id){const e=rcAtDa(id);if(!e)return;e.st='fim';e.hFim=hhmm(new Date());if(e.ag&&!RC.at.some(x=>x!==e&&x.ag===e.ag&&x.st!=='fim'))e.ag.sit='finalizado';rcHist(e,'procedimento','Concluído: '+rcProcsTxt(e.procs),e.local,e.prof);
 const prox=RC.at.find(x=>x.sid===e.sid&&x.st==='pendente'&&x.etapa);
 if(prox){prox.st='espera';prox.etapa=false;prox.motivo='';prox.ts=Date.now();RC.at.filter(x=>x.sid===e.sid&&x.st==='pendente'&&x.etapa).forEach(x=>x.motivo='Aguarda a etapa anterior: '+rcSetor(prox.setor).n);toast(`Próxima etapa: ${rcSetor(prox.setor).n}`)}
 else if(!RC.at.some(x=>x.sid===e.sid&&x.st!=='fim')){const s=RC.senhas.find(x=>x.id===e.sid);if(s)rcNps(s);RC.atTab='fim';toast('Atendimento concluído')}
 rcMudou()}
function rcAtObs(id){rcTextoModal('Observação ou intercorrência','Descreva',`rcAtObsOk(${id})`,'Registrar')}
function rcAtObsOk(id){const e=rcAtDa(id),v=$('#rcMot').value.trim();if(!v){toast('Descreva a observação','warn');return}rcHist(e,'procedimento','Observação ou intercorrência',v,e.prof);closeModal();toast('Observação registrada no histórico')}
/* Pós-atendimento: documentos, resultado, pendência e novo encaminhamento */
const RC_DOCS=['Atestado','Declaração de comparecimento','Receita','Recibo'];
function rcPosModal(id){const e=rcAtDa(id);if(!e)return;openModal(`${mh('Pós-atendimento · '+esc(e.pac||e.num))}<div class="mb"><h4 style="margin-bottom:6px">Documentos emitidos</h4><div class="at-list">${RC_DOCS.map((d,i)=>`<label class="at-row check"><input type="checkbox" id="rcPosD${i}"><div class="grow">${d}</div></label>`).join('')}<label class="at-row check"><input type="checkbox" id="rcPosR"><div class="grow">Resultado ou laudo disponível no portal</div></label></div><div class="field" style="margin-top:10px"><label for="rcPosP">Pendência</label><input class="in" id="rcPosP" placeholder="Opcional"></div><div class="field"><label for="rcPosE">Encaminhar a outro procedimento</label><select class="in" id="rcPosE"><option value="">Nenhum</option>${rcOpts(PROCEDIMENTOS.map(p=>[p.c,p.n]),'')}</select></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Voltar</button><button class="btn" onclick="rcPosOk(${id})">Registrar</button></div>`)}
function rcPosOk(id){const e=rcAtDa(id),s=RC.senhas.find(x=>x.id===e.sid),docs=RC_DOCS.filter((d,i)=>$('#rcPosD'+i).checked),res=$('#rcPosR').checked,pen=$('#rcPosP').value.trim(),c=$('#rcPosE').value;
 if(!docs.length&&!res&&!pen&&!c){toast('Marque ou preencha ao menos um item','warn');return}
 if(docs.length)rcHist(e,'pos','Documentos emitidos',docs.join(', '),e.prof);if(res)rcHist(e,'pos','Resultado ou laudo disponível',rcProcsTxt(e.procs),e.prof);if(pen)rcHist(e,'pos','Pendência registrada',pen,e.prof);
 if(c&&s){const ant=RC.guias.find(g=>g.sid===s.id),g=rcGuiaCriar(s,[c],ant?ant.conv:'Particular',0,0);rcEncaminhar(s,[c],{caixa:g.pagar>0}).forEach(x=>x.guia=g.num)}
 closeModal();rcMudou();toast(c?'Registrado e encaminhado':'Pós-atendimento registrado')}
function rcAtLiberar(id){const e=rcAtDa(id);if(!e)return;
 if(!e.setor){toast('Configure o setor deste grupo em Configurações da recepção','warn');return}
 if(e.ag&&!e.guia&&!e.cx){const r=clPodeChamar(e.ag);if(!r.ok&&!r.fim){toast('Falta: '+r.pend.join(', ').toLowerCase(),'warn');CL_FTAB='chamar';location.hash='#fila';return}}
 const antes=RC.at.find(x=>x.sid===e.sid&&x!==e&&['espera','atendimento'].includes(x.st));
 if(antes){e.etapa=true;e.motivo='Aguarda a etapa anterior: '+rcSetor(antes.setor).n;rcMudou();toast('Ainda há uma etapa anterior em andamento','warn');return}
 e.st='espera';e.motivo='';e.cx=false;e.ts=Date.now();rcHist(e,'recepcao','Entrou na espera: '+rcSetor(e.setor).n,rcProcsTxt(e.procs));const s=RC.at.filter(x=>x.sid===e.sid&&x.st==='pendente');s.forEach(x=>{x.etapa=true;x.motivo='Aguarda a etapa anterior: '+rcSetor(e.setor).n});rcMudou();toast('Liberado para a espera')}
function rcAtPeso(id,p){const e=rcAtDa(id);if(!e)return;e.peso=p;rcMudou();toast('Prioridade alterada: a ordem da fila foi atualizada')}
function rcAtLinhas(l,tipo){return l.map(e=>{const set=rcSetor(e.setor),proc=esc(e.procs.map(clProcNome).join(', '));
 const pac=`<div class="two">${esc(e.pac||'Sem identificação')}<small>${rcCod(e)}</small></div>`;
 const sen=`<div class="two"><span class="mono"><b>${esc(e.num)}</b></span><small>${esc(rcTipo(e.tipo).n)}${e.guia?' · guia '+esc(e.guia):''}</small></div>`,pe=`<select class="in" style="width:auto;height:28px;font-size:12px" aria-label="Prioridade de ${esc(e.num)}" onchange="rcAtPeso(${e.id},this.value)">${rcOpts(RC.cfg.pesos.filter(p=>p.ativo).map(p=>[p.id,p.n]),e.peso)}</select>`;
 if(tipo==='espera')return `<tr>${td('Senha',sen)}${td('Prioridade',`${rcPesoTag(e.peso)}<div style="margin-top:4px">${pe}</div>`)}${td('Paciente',pac)}${td('Procedimentos',proc)}${td('Setor',esc(set?set.n:'Sem setor'))}${td('Espera',`${rcMin(e.ts)} min<br><small class="tl">desde ${rcH(e.ts)}</small>`)}${td('',`<button class="btn sm" onclick="rcAtChamar(${e.id})">Chamar</button>`)}</tr>`;
 const loc=`<div class="two">${esc(set?set.n:'')}<small>${esc(e.local)}</small></div>`;
 if(tipo==='atendimento')return `<tr>${td('Senha',sen)}${td('Paciente',pac)}${td('Procedimentos',proc)}${td('Setor e local',loc)}${td('Profissional',esc(e.prof||'Não informado'))}${td('Operador',esc(e.op||'Não informado'))}${td('Início',e.hIni||'')}${td('',`<div class="row" style="gap:4px;flex-wrap:nowrap"><button class="btn sm ghost" onclick="rcAtChamar(${e.id})">Chamar de novo</button><button class="btn sm ghost" onclick="rcAtObs(${e.id})">Observação</button>${e.setor==='consult'?'<a class="btn sm ghost" href="#atendimento-medico">Prontuário</a>':''}<button class="btn sm" onclick="rcAtFinalizar(${e.id})">Finalizar</button></div>`)}</tr>`;
 if(tipo==='fim')return `<tr>${td('Senha',sen)}${td('Paciente',pac)}${td('Procedimentos',proc)}${td('Setor e local',loc)}${td('Profissional',esc(e.prof||'Não informado'))}${td('Concluído',e.hFim||'')}${td('',`<div class="row" style="gap:4px;flex-wrap:nowrap"><button class="btn sm sec" onclick="rcPosModal(${e.id})">Pós-atendimento</button>${e.cpf?`<button class="btn sm ghost" onclick="pacFicha('${e.cpf}','tempo')">Histórico</button>`:''}</div>`)}</tr>`;
 return `<tr>${td('Senha',sen)}${td('Paciente',pac)}${td('Procedimentos',proc)}${td('Setor',esc(set?set.n:'Sem setor'))}${td('Motivo',esc(e.motivo||''))}${td('',e.cx?'<a class="btn sm sec" href="#caixa">Ir ao Caixa</a>':e.etapa?'<span class="tl">segue sozinho</span>':`<button class="btn sm sec" onclick="rcAtLiberar(${e.id})">Liberar</button>`)}</tr>`}).join('')}
VIEWS.atendimentos=()=>{rc();const vis=rcSetoresVis().map(s=>s.id),sel=RC.atSetor&&vis.includes(RC.atSetor)?RC.atSetor:'';
 const base=RC.at.filter(e=>e.unid===RC.unid&&(!sel?vis.includes(e.setor)||!e.setor:e.setor===sel));
 const esp=rcOrdem(base.filter(e=>e.st==='espera'),{...RC.cfg,modo:'peso'}),em=base.filter(e=>e.st==='atendimento'),pen=base.filter(e=>e.st==='pendente'),fim=base.filter(e=>e.st==='fim');
 const T=RC.atTab;const ths={espera:['Senha','Prioridade','Paciente','Procedimentos','Setor','Espera',''],atendimento:['Senha','Paciente','Procedimentos','Setor e local','Profissional','Operador','Início',''],pendente:['Senha','Paciente','Procedimentos','Setor','Motivo',''],fim:['Senha','Paciente','Procedimentos','Setor e local','Profissional','Concluído','']};
 const vaz={espera:'Ninguém em espera',atendimento:'Ninguém em atendimento',pendente:'Nenhuma pendência',fim:'Nenhum atendimento concluído'},lst={espera:esp,atendimento:em,pendente:pen,fim};
 return `<div class="rc-atit"><h1>Atendimento</h1></div>
 <div class="row" style="justify-content:space-between;gap:8px;flex-wrap:wrap"><div class="row" style="gap:6px;flex-wrap:wrap">${rcSetoresVis().length>1?chip('Todos os setores',!sel,"RC.atSetor='';reView()"):''}${rcSetoresVis().map(s=>chip(esc(s.n),sel===s.id,`RC.atSetor='${s.id}';reView()`)).join('')}</div><button class="btn" onclick="naNovo('atendimento')">${I.plus} Novo atendimento</button></div>
 <div style="margin-top:10px">${rcTabs([['espera','Espera',esp.length],['atendimento','Em atendimento',em.length],['pendente','Pendente',pen.length],['fim','Concluídos',fim.length],['hoje','Todos de hoje',ATENDS.length+clAgendaHoje().filter(a=>!['Coleta','Domiciliar'].includes(a.tipo)).length]],T,'RC.atTab')}</div>
 ${T==='hoje'?atHoje():tabela(ths[T],lst[T].length?[rcAtLinhas(lst[T],T)]:[],vaz[T])}`};
/* A ordem considera o tempo de espera: refaz a lista a cada minuto */
setInterval(()=>{if(RC_OK&&location.hash==='#atendimentos')reView()},60000);

/* ---------- Pré-atendimento e totem ---------- */
const rcBuscaPac=q=>{const t=semAc(q.trim()),d=soDig(q);if(t.length<2&&d.length<3)return [];return PACIENTES.filter(p=>p.ativo&&(semAc(p.n).includes(t)&&t.length>=2&&!/^\d/.test(t)||(d.length>=3&&(soDig(p.cpf).includes(d)||soDig(p.tel).includes(d)))))};
/* Novo cadastro já traz o que foi digitado na busca */
const rcPaPre=()=>{const q=RC.pa.q.trim(),d=soDig(q);return /[a-zà-ú]/i.test(q)?{n:q}:/\(/.test(q)||d.length===10?{tel:mTel(q)}:{cpf:mCPF(q)}};
const rcBuscaNomeCpf=q=>{const t=semAc(q.trim()),d=soDig(q);if(/^[\d.\-\s]+$/.test(q.trim()))return d.length>=3?PACIENTES.filter(p=>p.ativo&&soDig(p.cpf).includes(d)):[];return t.length>=2?PACIENTES.filter(p=>p.ativo&&semAc(p.n).includes(t)):[]};
function rcPaResultados(){const l=rcBuscaNomeCpf(RC.pa.q);if(!RC.pa.q.trim())return '';
 if(!l.length)return `<div class="empty" style="padding:14px 8px"><h4>Ninguém encontrado</h4><p>Confira o que digitou ou faça o cadastro.</p><button class="btn sm sec" onclick="rcPacEditar('',rcPaPre())">Cadastrar paciente</button></div>`;
 return `<div class="at-list" style="margin-top:8px">${l.slice(0,6).map(p=>`<div class="at-row clk" onclick="RC.pa.cpf='${p.cpf}';reView()"><div class="grow"><b>${esc(p.n)}</b><small><span class="mono">${cpfMask(p.cpf)}</span> · ${dmy(p.dn)} · ${esc(p.tel)}</small></div><span class="btn sm sec">Selecionar</span></div>`).join('')}</div>`}
const rcPesoChips=(cur,oc,sem)=>`<div class="cl-jpick">${RC.cfg.pesos.filter(p=>rcPesoUnid(p,RC.unid)&&!(sem&&p.sempre)).map(p=>`<button type="button" class="chip ${cur===p.id?'on':''}" onclick="${oc.replace('#',p.id)}">${esc(p.n)}</button>`).join('')}</div>`;
const rcTipos=()=>RC.cfg.tipos.filter(t=>t.ativo&&t.unids.includes(RC.unid));
const rcTicket=s=>`<div class="rc-tick"><div class="tl">Sua senha</div><div class="sn">${esc(s.num)}</div><div>${s.pac?esc(s.pac)+' · ':''}${rcPesoTag(s.peso)}</div><p class="tl" style="margin-top:6px">${rcUnidNome(s.unid)} · ${s.h}. Aguarde a chamada no painel.</p></div>`;
/* Nota 148: prévia antes de imprimir; a impressão leva só a senha */
function rcSenhaPrevia(id){const s=RC.senhas.find(x=>x.id===id);if(!s)return;openModal(`${mh('Prévia da senha')}<div class="mb"><div class="rc-prev">${rcTicket(s)}</div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn" onclick="rcSenhaImprimir(${id})">${I.print} Imprimir</button></div>`)}
function rcSenhaImprimir(id){const s=RC.senhas.find(x=>x.id===id);if(!s)return;const fr=document.createElement('iframe');fr.style.cssText='position:fixed;width:0;height:0;border:0';fr.srcdoc=`<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><title>Senha ${esc(s.num)}</title><style>@page{size:80mm auto;margin:4mm}body{font-family:Arial,sans-serif;text-align:center;color:#000}.n{font-size:40pt;font-weight:700;margin:6px 0}p{margin:4px 0;font-size:11pt}</style></head><body><p>Sua senha</p><div class="n">${esc(s.num)}</div>${s.pac?`<p>${esc(s.pac)}</p>`:''}<p>${esc(rcPeso(s.peso).n)}</p><p>${esc(rcUnidNome(s.unid))} · ${esc(s.h)}</p><p>Aguarde a chamada no painel.</p></body></html>`;fr.onload=()=>{fr.contentWindow.focus();fr.contentWindow.print();setTimeout(()=>fr.remove(),60000)};document.body.appendChild(fr)}
function rcPaGerar(){const p=rcPacCpf(RC.pa.cpf);if(!p){toast('Selecione o paciente','warn');return}if(!rcAgDoDia(p.n)&&!RC.cfg.semAg.includes(RC.unid)){toast('Esta unidade só atende com agendamento','warn');return}const r=rcGerarSenha({pac:p.n,cpf:p.cpf,tipo:RC.pa.tipo,peso:RC.pa.peso});if(r.erro){toast(r.erro,'warn');return}RC.pa.ult=r.senha.id;RC.pa.cpf='';RC.pa.q='';RC.pa.peso='NOR';rcMudou();toast(`Senha ${r.senha.num} gerada`)}
VIEWS['pre-atendimento']=()=>{rc();const pa=RC.pa,p=rcPacCpf(pa.cpf),ult=RC.senhas.find(s=>s.id===pa.ult),rec=RC.senhas.filter(s=>s.unid===RC.unid).slice(-5).reverse();if(!rcTipos().some(t=>t.id===pa.tipo))pa.tipo=(rcTipos()[0]||{}).id;
 const oper=`<div class="grid g2 rc-pa"><div class="card"><h3>1. Localizar cliente</h3><div class="inwrap" style="margin-top:8px">${LUPA}<input class="in" placeholder="Busque pelo nome ou CPF do cliente" value="${esc(pa.q)}" oninput="RC.pa.q=this.value;$('#rcPaRes').innerHTML=rcPaResultados()" aria-label="Busque pelo nome ou CPF do cliente"></div><div id="rcPaRes">${rcPaResultados()}</div></div>
 <div class="card"><h3>2. Gerar senha</h3>${p?`<div class="at-row" style="margin:8px 0"><div class="grow"><b>${esc(p.n)}</b><small><span class="mono">${cpfMask(p.cpf)}</span> · ${dmy(p.dn)}</small></div><button class="btn sm ghost" onclick="RC.pa.cpf='';reView()">Trocar</button></div>${(g=>g?`<p class="tl">Agendado hoje às ${g.h}: ${esc(rcProcsTxt(g.itens))}. A senha confirma a chegada.</p>`:`<p class="tl">Sem agendamento hoje${RC.cfg.semAg.includes(RC.unid)?': segue como atendimento avulso.':'. Esta unidade só atende com agendamento.'}</p>`)(rcAgDoDia(p.n))}`:''}
 <div ${p?'':'inert class="rc-off"'}><div class="field"><label for="rcPaTipo">Tipo de senha</label><select class="in" id="rcPaTipo" onchange="RC.pa.tipo=this.value">${rcOpts(rcTipos().map(t=>[t.id,t.n]),pa.tipo)}</select></div>
 <h4 style="margin:10px 0 6px">Peso do atendimento</h4>${rcPesoChips(pa.peso,"RC.pa.peso='#';reView()")}
 <div class="row" style="margin-top:12px"><button class="btn" ${p?'':'disabled'} onclick="rcPaGerar()">Gerar Senha</button></div></div>
 ${ult?`<div style="margin-top:12px">${rcTicket(ult)}<div class="row" style="justify-content:center;margin-top:8px"><button class="btn sm sec" onclick="rcSenhaPrevia(${ult.id})">${I.print} Imprimir</button><a class="btn sm ghost" href="#senhas" onclick="RC.tab='aguardando';RC.foco=${ult.id}">Ver na listagem</a></div></div>`:''}</div></div>
 <div class="rc-pa-lista"><h3 style="margin:28px 0 10px">Últimas senhas geradas</h3>${tabela(['Senha','Paciente','Peso','Gerada'],rec.map(s=>`<tr>${td('Senha',`<span class="mono"><b>${esc(s.num)}</b></span>`)}${td('Paciente',s.pac?esc(s.pac):'<span class="tl">sem identificação</span>')}${td('Peso',rcPesoTag(s.peso))}${td('Gerada',s.h)}</tr>`),'Nenhuma senha gerada')}</div>`;
 return `${pageHead('Recepção','Pré-atendimento','')}<div style="margin-top:12px">${oper}</div>`};
function rcTotCpf(){const d=soDig(RC.tot.cpf);if(d.length!==11){toast('Digite os 11 números do CPF','warn');return}const p=PACIENTES.find(x=>soDig(x.cpf)===d&&x.ativo);if(!p){toast('CPF não encontrado. Continue sem CPF e identifique-se no guichê','warn');return}RC.tot.pac=p;RC.tot.passo=2;reView()}
function rcTotGerar(peso){const p=RC.tot.pac,r=rcGerarSenha({pac:p?p.n:'',cpf:p?p.cpf:'',tipo:rcTipos()[0]&&rcTipos()[0].id,peso,orig:'totem'});if(r.erro){toast(r.erro,'warn');return}RC.tot.ult=r.senha.id;RC.tot.passo=3;rcMudou()}

/* ---------- Listagem de senhas ---------- */
function rcSenhaAcoes(s){const em=RC.at.filter(e=>e.sid===s.id&&e.st!=='fim');
 if(s.st==='aguardando')return `<button class="btn sm sec" onclick="rcChamarFora(${s.id})">Chamar</button><button class="btn sm ghost" onclick="rcCancelarModal(${s.id})">Cancelar</button>`;
 if(s.st==='chamada')return `<button class="btn sm" onclick="rcIniciar(${s.id})">Iniciar</button><button class="btn sm sec" onclick="rcRechamar(${s.id})">Rechamar</button><button class="btn sm ghost" onclick="rcCancelarModal(${s.id})">Cancelar</button>`;
 if(s.st==='atendimento')return `<button class="btn sm" onclick="rcFinalizarModal(${s.id})">Finalizar</button>${s.cpf?`<button class="btn sm sec" onclick="naNovo('atendimento','${s.cpf}',false,true)">Novo atendimento</button>`:''}`;
 if(em.length){const e=em.find(x=>x.st==='espera');return e?`<button class="btn sm sec" onclick="rcAtChamar(${e.id})">Chamar</button>`:em.some(x=>x.cx)?'<a class="btn sm" href="#caixa">Ir ao Caixa</a>':`<a class="btn sm ghost" href="#atendimentos">Ver em Atendimentos</a>`}
 if(s.nps)return `<select class="in" style="width:auto;height:28px;font-size:12px" aria-label="Nota da pesquisa" onchange="rcNotaNps(${s.id},this.value)"><option value="">Nota da pesquisa</option>${[...Array(11).keys()].map(n=>`<option ${String(s.nps.nota)===String(n)?'selected':''}>${n}</option>`).join('')}</select>`;
 return ''}
function rcNotaNps(id,v){const s=RC.senhas.find(x=>x.id===id);if(s&&s.nps){s.nps.nota=v;toast(v===''?'Nota apagada':`Nota ${v} registrada na pesquisa de satisfação`)}}
function rcSenhaSit(s){const e=RC.at.find(x=>x.sid===s.id&&x.st!=='fim');
 if(s.st==='chamada')return `Chamada ${s.nCham}x · ${esc(s.local)}`;if(s.st==='atendimento')return `${esc(s.local)} · desde ${s.hIni}`;if(s.st==='cancelada')return 'Cancelada: '+esc(s.motivo||'');
 if(s.st==='finalizada'&&e)return `${esc((rcSetor(e.setor)||{n:'Sem setor'}).n)} · ${e.st==='espera'?'em espera':e.st==='atendimento'?'em atendimento':e.cx?'aguarda o Caixa':'pendente'}`;
 if(s.st==='finalizada')return 'Concluído'+(s.nps?` · pesquisa enviada${s.nps.nota!==''?', nota '+s.nps.nota:''}`:'');return rcMin(s.ts)+' min aguardando'}
function rcSenhaRows(){const q=semAc(RC.q.trim()),d=soDig(RC.q),t=RC.tab,base=RC.senhas.filter(s=>s.unid===RC.unid&&(!q||semAc(s.pac).includes(q)||semAc(s.num).includes(q)||(d.length>=3&&soDig(s.cpf).includes(d))));
 let l=t==='setor'?base.filter(s=>s.st==='finalizada'&&RC.at.some(e=>e.sid===s.id&&e.st!=='fim')):t==='finalizada'?base.filter(s=>s.st==='finalizada'&&!RC.at.some(e=>e.sid===s.id&&e.st!=='fim')):base.filter(s=>s.st===t);
 if(t==='aguardando')l=rcOrdem(l,RC.cfg,RC.ptr);
 if(!l.length)return vazioLinha(8,t==='aguardando'?'Ninguém aguardando':'Nenhuma senha aqui',q?'Mude a busca.':t==='aguardando'?'As senhas do Pré-atendimento e do totem aparecem aqui.':'');
 return l.map((s,i)=>`<tr id="rcS${s.id}" class="${RC.foco===s.id?'rc-foco':''}">${td('Senha',`<span class="mono"><b>${esc(s.num)}</b></span>${t==='aguardando'&&i===0?' <span class="badge acc">próxima</span>':''}`)}${td('Paciente',s.pac?`<div class="two">${esc(s.pac)}<small>${rcCod(s)}</small></div>`:'<span class="tl">sem identificação</span>')}${td('CPF',s.cpf?`<span class="mono">${cpfMask(s.cpf)}</span>`:'<span class="tl">não informado</span>')}${td('Tipo',esc(rcTipo(s.tipo).n))}${td('Peso',rcPesoTag(s.peso))}${td('Gerada',s.h)}${td('Situação',`<span title="${esc(s.log.join(' · '))}">${rcSenhaSit(s)}</span>`)}${td('',`<div class="row" style="gap:4px;flex-wrap:nowrap">${rcSenhaAcoes(s)}</div>`)}</tr>`).join('')}
VIEWS.senhas=()=>{rc();const u=RC.senhas.filter(s=>s.unid===RC.unid),c=k=>u.filter(s=>s.st===k).length,setor=u.filter(s=>s.st==='finalizada'&&RC.at.some(e=>e.sid===s.id&&e.st!=='fim')).length,g=rcMeuGuiche();
 return `${pageHead('Recepção','Listagem de Senhas',`Quem aguarda, quem foi chamado e quem está em atendimento em ${rcUnidNome(RC.unid)}.`,`<a class="btn sec" href="#painel-senhas">Painel de Senhas</a><a class="btn sec" href="#pre-atendimento">${I.plus} Gerar senha</a>`)}
 <div class="filters"><div class="inwrap" style="flex:1 1 220px">${LUPA}<input class="in" placeholder="Senha, nome ou CPF" value="${esc(RC.q)}" oninput="RC.q=this.value;$('#rcSBody').innerHTML=rcSenhaRows()" aria-label="Buscar senha"></div>
 <select class="in" style="width:auto" aria-label="Meu guichê" onchange="RC.meuG=this.value;reView()">${rcOpts(rcGuiches().filter(x=>x.ativo).map(x=>[x.id,x.n+(x.op?' · '+x.op:'')]),g?g.id:'')}</select><button class="btn" onclick="rcProxima()">Chamar próxima</button></div>
 ${rcTabs([['aguardando','Aguardando',c('aguardando')],['chamada','Chamados',c('chamada')],['atendimento','Em atendimento',c('atendimento')],['setor','Nos setores',setor],['finalizada','Concluídos',c('finalizada')-setor],['cancelada','Cancelados',c('cancelada')]],RC.tab,'RC.tab')}
 <div class="tablewrap" style="margin-top:10px"><table class="at-table"><thead><tr>${['Senha','Paciente','CPF','Tipo','Peso','Gerada','Situação',''].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody id="rcSBody">${rcSenhaRows()}</tbody></table></div>`};

/* ---------- Painel de senhas e TV ---------- */
function rcFala(c){if(!RC.voz||typeof speechSynthesis==='undefined'||!/^#painel-(tv|senhas)/.test(location.hash))return;try{const u=new SpeechSynthesisUtterance(`${c.n||'Senha '+c.num.replace('-',' ')}, ${c.local}`);u.lang='pt-BR';speechSynthesis.speak(u)}catch(e){}}
const rcPainelLista=()=>RC.chamadas.filter(c=>c.unid===RC.painel.unid&&(RC.painel.qual==='todos'||c.painel===RC.painel.qual));
const rcQual=()=>RC.painel.qual==='todos'?'Todos os painéis':RC.painel.qual==='rec'?'Recepção':(rcSetor(RC.painel.qual)||{n:''}).n;
let rcCanal=null;try{rcCanal=new BroadcastChannel('deoclinic-painel')}catch(e){}
function rcPublica(){if(rcCanal)try{rcCanal.postMessage({t:'estado',chamadas:RC.chamadas,painel:RC.painel,setores:RC.cfg.setores})}catch(e){}}
if(rcCanal)rcCanal.onmessage=ev=>{const d=ev.data||{};if(d.t==='pedir'){if(RC_OK&&!/^#painel-tv/.test(location.hash))rcPublica();return}
 if(d.t==='estado'&&/^#painel-tv/.test(location.hash)){const novo=d.chamadas[0],era=RC.chamadas[0];RC.chamadas=d.chamadas;RC.painel=d.painel;RC.cfg.setores=d.setores;if(novo&&(!era||novo.ts!==era.ts))rcFala(novo);reView()}};
const rcTvCorpo=()=>{const l=rcPainelLista(),c=l[0];return `<div><div class="un">${esc(rcUnidNome(RC.painel.unid))} · ${esc(rcQual())}</div>${c?`<div role="status" aria-live="polite"><div class="sn">${esc(c.num)}</div><div class="nm">${esc(c.n||'')}</div><div class="lc">${esc(c.local)}</div><div style="margin-top:1vw"><span class="badge ${rcPeso(c.peso).cor}">${esc(rcPeso(c.peso).n)}</span> <span class="un">${esc(c.cod||'')}</span></div></div>`:'<div class="nm" style="margin-top:4vw">Aguardando chamadas</div>'}</div><div><h2>Últimas chamadas</h2>${l.slice(1,7).map(x=>`<div class="h"><b>${esc(x.num)}</b><span>${esc(x.local)}</span><span>${x.h}</span></div>`).join('')||'<div class="h">Nenhuma ainda</div>'}</div>`};
VIEWS['painel-tv']=()=>{rc();if(rcCanal&&!RC.tvPediu){RC.tvPediu=true;try{rcCanal.postMessage({t:'pedir'})}catch(e){}}return `<div class="rc-tvv">${rcTvCorpo()}<button class="btn sm ghost sair" style="color:#fff" onclick="if(document.fullscreenElement)document.exitFullscreen();if(window.opener)window.close();else location.hash='#painel-senhas'">Sair</button></div>`};
function rcAbrirTv(){const de=document.documentElement;if(de.requestFullscreen)de.requestFullscreen().catch(()=>{});location.hash='#painel-tv'}
