function rcPacEditar(cpf,pre){const p=cpf?rcPacCpf(cpf):null,a=p||{sx:'F',...pre,ativo:true},c=(k,d)=>esc(a[k]??d??''),i=(id,lab,sp,extra,cls)=>`<div class="field ${sp}"><label for="${id}">${lab}</label><input class="in ${cls||''}" id="${id}" ${extra||''}></div>`;
 RC.pEd=cpf||'';RC.pVj=!!(pre&&pre.vj);RC.cepUlt=soDig(a.cep);const rq=' <span class="req">*</span>';
 openModal(`${mh(p?'Editar cadastro':'Novo paciente')}<div class="mb"><div class="pf-g">
 ${i('pfN','Nome completo'+rq,'s6',`value="${c('n')}"`,'cx')}${i('pfMae','Nome da mãe'+rq,'s6',`value="${c('mae')}"`,'cx')}${i('pfC','CPF'+rq,'s2',`value="${c('cpf')}" ${p?'disabled':''} oninput="this.value=mCPF(this.value)"`)}${i('pfD','Nascimento'+rq,'s2',`type="date" value="${c('dn')}"`)}
 <div class="field s2"><label for="pfS">Sexo${rq}</label><select class="in" id="pfS">${rcOpts([['F','Feminino'],['M','Masculino']],a.sx)}</select></div></div>
 <h4 style="margin:12px 0 6px">Contato</h4><div class="pf-g">${i('pfT','Telefone'+rq,'s2',`value="${c('tel')}" oninput="this.value=mTel(this.value)"`)}${i('pfE','E-mail'+rq,'s4',`type="email" value="${c('email')}"`)}</div>
 <h4 style="margin:12px 0 6px">Endereço</h4><div class="pf-g"><div class="field s2"><label for="pfCep">CEP${rq}</label><input class="in" id="pfCep" value="${c('cep')}" inputmode="numeric" maxlength="9" placeholder="00000-000" oninput="this.value=mCep(this.value);rcCepBusca(this.value)"><span class="msg" id="pfCepMsg"></span></div><div class="field s1"><label for="pfUf">UF${rq}</label><select class="in" id="pfUf"><option value=""></option>${RC_UFS.map(u=>`<option ${a.uf===u?'selected':''}>${u}</option>`).join('')}</select></div>${i('pfCid','Cidade'+rq,'s3',`value="${c('cidade')}"`,'cx')}${i('pfRua','Rua ou avenida'+rq,'s4',`value="${c('rua')}"`,'cx')}${i('pfNum','Número'+rq,'s2',`value="${c('num')}"`,'cx')}${i('pfBai','Bairro'+rq,'s3',`value="${c('bairro')}"`,'cx')}${i('pfCom','Complemento (opcional)','s3',`value="${c('compl')}"`,'cx')}</div>
 ${p?`<div style="margin-top:10px">${rcSwitch(a.ativo,'','Cadastro ativo').replace('type="checkbox"','type="checkbox" id="pfAt"')}</div>`:''}
 </div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="rcPacSalvar()">Salvar</button></div>`,'wide')}
/* CEP (nota 131): consulta pública ViaCEP; sem resposta, o endereço é digitado à mão */
async function rcCepBusca(v){const d=soDig(v),m=$('#pfCepMsg');if(d.length!==8){RC.cepUlt='';if(m)m.textContent='';return}if(d===RC.cepUlt)return;RC.cepUlt=d;if(m){m.textContent='Buscando o endereço...';m.style.color=''}
 const av=(t,erro)=>{const x=$('#pfCepMsg');if(x){x.textContent=t;x.style.color=erro?'var(--err)':''}};
 try{const r=await fetch('https://viacep.com.br/ws/'+d+'/json/'),j=await r.json();if(!$('#pfCep')||soDig($('#pfCep').value)!==d)return;if(j.erro){av('CEP não encontrado: preencha o endereço.',true);return}
  const po=(id,val)=>{if(val)$('#'+id).value=id==='pfUf'?val:rcCaixaAlta(val)};po('pfUf',j.uf);po('pfCid',j.localidade);po('pfBai',j.bairro);po('pfRua',j.logradouro);av('Endereço preenchido pelo CEP. Confira e informe o número.');$('#pfNum').focus()}
 catch(e){av('Não foi possível consultar o CEP agora: preencha o endereço.',true)}}
function rcPacValidar(d,novo){if(!d.n)return 'Informe o nome';if(!d.mae)return 'Informe o nome da mãe';if(soDig(d.cpf).length!==11)return 'CPF precisa de 11 números';if(novo&&PACIENTES.some(p=>soDig(p.cpf)===soDig(d.cpf)))return 'Já existe cadastro com este CPF';if(!d.dn)return 'Informe o nascimento';if(soDig(d.tel).length<10)return 'Informe o telefone com DDD';if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(d.email||''))return 'Informe um e-mail válido';if(!/^\d{5}-\d{3}$/.test(d.cep||''))return 'Informe o CEP no formato 00000-000';if(!d.uf)return 'Informe o estado (UF)';if(!d.cidade)return 'Informe a cidade';if(!d.rua)return 'Informe a rua ou avenida';if(!d.num)return 'Informe o número (ou S/N)';if(!d.bairro)return 'Informe o bairro';return ''}
function rcPacSalvar(){const v=id=>($('#'+id).value||'').trim(),novo=!RC.pEd,ant=novo?null:rcPacCpf(RC.pEd),nome=rcCaixaAlta(v('pfN')),d={n:ant&&rcCaixaAlta(ant.n)===nome?ant.n:nome,cpf:mCPF(v('pfC')),mae:rcCaixaAlta(v('pfMae')),dn:v('pfD'),sx:v('pfS'),tel:v('pfT'),email:v('pfE'),cep:mCep(v('pfCep')),uf:v('pfUf'),cidade:rcCaixaAlta(v('pfCid')),bairro:rcCaixaAlta(v('pfBai')),rua:rcCaixaAlta(v('pfRua')),num:rcCaixaAlta(v('pfNum')),compl:rcCaixaAlta(v('pfCom')),ativo:novo?true:!!$('#pfAt').checked};
 const e=rcPacValidar(d,novo);if(e){toast(e,'warn');return}
 if(novo){PACIENTES.unshift({...d,tel2:'',wa1:true,wa2:false,cron:['Não','Não']});if(location.hash==='#pre-atendimento'){RC.pa.cpf=d.cpf;RC.pa.q=''}if(location.hash==='#agendamento')RC.agd.cpf=d.cpf}else Object.assign(ant,d);
 rcHist(d,'recepcao',novo?'Cadastro criado':'Cadastro atualizado');closeModal();reView();toast(novo?'Paciente cadastrado':'Cadastro atualizado');if(novo&&RC.pVj&&RC.vj){RC.pVj=false;RC.vj.l=[rcPacCpf(d.cpf)];rcVjEsc(0)}}
function pacNovo(){rcPacEditar()}

/* ---------- Agendas e vagas ---------- */
const rcDiaBr=d=>d.slice(8,10)+'/'+d.slice(5,7);
const rcDiaSem=d=>new Date(d+'T12:00').getDay();
const rcDiaLongo=d=>['Domingo','Segunda-Feira','Terça-Feira','Quarta-Feira','Quinta-Feira','Sexta-Feira','Sábado'][rcDiaSem(d)]+' '+rcDiaBr(d)+'/'+d.slice(0,4); /* nota 257 */
const rcDiaTxt=d=>['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'][rcDiaSem(d)]+' '+rcDiaBr(d);
const rcSomaDia=(d,n)=>{const x=new Date(d+'T12:00');x.setDate(x.getDate()+n);return iso(x)};
const rcDiaAberto=(a,d)=>a.datas?!!a.datas[d]:d>=a.de&&d<=a.ate&&a.dias.includes(rcDiaSem(d));
const rcEhChegada=h=>h.startsWith('Chegada');
const rcHoraTxt=h=>rcEhChegada(h)?'por ordem de chegada':'às '+h;
function rcSlots(a,d){const c=a.datas?a.datas[d]:a;if(!c)return [];const ps=c.periodos||[c],m=s=>+s.slice(0,2)*60+ +s.slice(3),r=[];let nc=0;ps.forEach(p=>{if((p.modo||c.modo)==='chegada'){for(let i=0;i<(+p.total||0);i++)r.push('Chegada '+String(++nc).padStart(2,'0'));return}const du=Math.max(5,+p.dur||20);for(let t=m(p.ini);t+du<=m(p.fim);t+=du)r.push(String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0'))});return r}
/* Nota 172: o período daquele horário define os procedimentos e a sala */
function rcPerDoHorario(a,d,h){const c=a.datas?a.datas[d]:a;if(!c)return null;const ps=c.periodos||[c];if(rcEhChegada(h)){let n=+h.slice(8);for(const p of ps){if((p.modo||c.modo)!=='chegada')continue;const t=+p.total||0;if(n<=t)return p;n-=t}return null}const m=rcMinDe(h);return ps.find(p=>(p.modo||c.modo)!=='chegada'&&m>=rcMinDe(p.ini)&&m<rcMinDe(p.fim))||null}
const rcProcsDoHorario=(a,d,h)=>{const p=rcPerDoHorario(a,d,h);return p&&p.procs&&p.procs.length?a.procs.filter(c=>p.procs.includes(c)):a.procs};
/* Nota 268: Em espera entra sozinho quando a guia é gerada */
const rcStDe=(s,esp)=>s==='finalizado'?'FINALIZADO':s==='faltou'||s==='cancelado'?null:esp?'EM ESPERA':s==='agendado'?'AGENDADO':'CONFIRMADO';
const rcAgSit=s=>s==='finalizado'?'Concluído':s[0].toUpperCase()+s.slice(1);
function rcMarcados(prof,d){const hj=d===RC_HOJE?clAgendaHoje().filter(a=>a.prof===prof).map(a=>({h:a.h,pac:a.pac,itens:a.itens,src:a.src,ref:a.ref,st:rcStDe(a.sit,(a.src||a).emEspera)})):[];
 const fut=d===RC_HOJE?[]:[...RC.ag.filter(a=>a.prof===prof&&a.data===d),...[...CL_AG_NOVOS,...CL_AG_EXTRA].filter(a=>a.prof===prof&&a.dia===rcDiaBr(d))].map(a=>({h:a.h,pac:a.pac,itens:a.itens,src:a,st:rcStDe(a.sit,a.emEspera)}));
 return [...hj,...fut].filter(m=>m.st)}
const rcBk=(prof,d,h)=>prof+'|'+d+'|'+h;
function rcVagasProf(prof,d,unid){const ags=RC.agendas.filter(a=>a.prof===prof&&(!unid||a.unid===+unid)&&rcDiaAberto(a,d)),m=rcMarcados(prof,d),hs=new Set([...ags.flatMap(a=>rcSlots(a,d)),...m.map(x=>x.h)]);
 return [...hs].sort().map(h=>{const e=m.find(x=>x.h===h);return e?{h,st:e.st,ev:e}:{h,st:RC.bloq.has(rcBk(prof,d,h))?'VAGA BLOQUEADA':'VAGA DISPONÍVEL'}})}
function rcLivres(a,d){if(d<RC_HOJE||!rcDiaAberto(a,d))return [];const t=rcVagasProf(a.prof,d);const hs=new Set(rcSlots(a,d));return t.filter(v=>v.st==='VAGA DISPONÍVEL'&&hs.has(v.h)).map(v=>v.h)}
const rcAgCod=()=>'AG-'+String(++RC.seqAg).padStart(5,'0');
function rcAgendar({agenda,data,h,cpf,proc,conv,alt}){const a=RC.agendas.find(x=>x.id===agenda),p=rcPacCpf(cpf);
 if(!p)return {erro:'Selecione o paciente.'};if(!p.ativo)return {erro:'Paciente inativo não pode ser agendado.'};if(!a)return {erro:'Agenda não encontrada.'};
 if(!a.procs.includes(proc))return {erro:'Este procedimento não faz parte da agenda.'};
 if(!rcProcsDoHorario(a,data,h).includes(proc))return {erro:'Este procedimento não é realizado neste período da agenda.'};
 if(!rcLivres(a,data).includes(h))return {erro:`O horário ${h} de ${rcDiaBr(data)} não está disponível com ${PROF(a.prof).n}.`};
 const tipo=(PROC(proc)||{}).tipo||'Consulta',x={cod:alt?alt.cod:rcAgCod(),h,data,pac:p.n,cpf:p.cpf,itens:[proc],prof:a.prof,sala:(rcPerDoHorario(a,data,h)||{}).sala||clSalaAg({proc,prof:a.prof}),tipo,sit:'agendado',conv:conv||'Particular',pago:false,agenda:a.id,unid:a.unid,dia:data===RC_HOJE?'hoje':rcDiaBr(data),quando:hhmm(new Date())};
 if(alt){rcSai(RC.ag,alt);rcSai(CL_AG_NOVOS,alt)}
 RC.ag.push(x);if(data===RC_HOJE)CL_AG_NOVOS.push(x);rcHist(x,'agenda',`Agendamento ${x.cod} ${alt?'alterado':'criado'}`,`${alt?`De ${rcDiaBr(alt.data)} ${alt.h} para `:''}${rcDiaBr(data)} ${h} · ${clProcNome(proc)} · ${x.conv}`,PROF(a.prof).n);return {ok:x}}
/* Cancelar mantém o registro e libera o horário */
function rcDesmarcar(x,mot){x.sit='cancelado';x.motivo=mot;rcSai(CL_AG_NOVOS,x);rcHist(x,'agenda',`Agendamento ${x.cod||x.h} cancelado`,mot,(PROF(x.prof)||{}).n)}

/* ---------- Agendamento (nota 29) ---------- */
const rcAgdPacLista=()=>{const f=RC.agd.f,tem=f.n||f.cpf||f.tel||f.guia,l=tem?rcPacFiltrar(f):[];if(!tem)return '<p class="tl" style="margin-top:8px">Use os filtros para localizar o paciente.</p>';if(!l.length)return `<div class="empty" style="padding:14px 8px"><h4>Ninguém encontrado</h4><button class="btn sm sec" onclick="rcPacEditar('',{n:RC.agd.f.n,cpf:RC.agd.f.cpf,tel:RC.agd.f.tel})">Cadastrar paciente</button></div>`;
 return `<div class="at-list" style="margin-top:8px">${l.slice(0,6).map(p=>`<div class="at-row clk" onclick="${p.cpf?`RC.agd.cpf='${p.cpf}';reView()`:`toast('Este cadastro está sem CPF: complete o cadastro para agendar','warn')`}"><div class="grow"><b>${esc(p.n)}</b><small><span class="mono">${cpfMask(p.cpf)}</span> · ${dmy(p.dn)} · ${esc(p.tel)}</small></div><span class="btn sm sec">Selecionar</span></div>`).join('')}</div>`};
function agdFiltro(k,v){if(!k){RC.agd.f={n:'',cpf:'',tel:'',guia:'',st:'ativos'};reView();return}RC.agd.f[k]=v;$('#rcAgdLista').innerHTML=rcAgdPacLista()}
function rcAgdAgendas(){const f=RC.agd;return RC.agendas.filter(a=>(!f.unid||a.unid===+f.unid)&&(!f.prof||a.prof===f.prof)&&(!f.proc||a.procs.includes(f.proc)))}
function rcProxVaga(a,de){for(let i=0;i<90;i++){const d=rcSomaDia(de,i);if(rcLivres(a,d).length)return d}return ''}
/* Notas 195 a 198: CPF vazio não localiza ninguém (antes achava o cadastro sem CPF e a tela não mudava). A troca desfaz o vínculo com a alteração ou o pré-agendamento de quem saiu */
const rcAgdPac=()=>RC.agd.cpf?rcPacCpf(RC.agd.cpf):null;
function rcAgdTrocar(){const A=RC.agd;A.cpf='';A.alt=null;A.pre=null;A.f={n:'',cpf:'',tel:'',guia:'',st:'ativos'};reView();toast('Localize o novo paciente');const i=$('#view .filters input');if(i)i.focus()}
VIEWS.agendamento=()=>{rc();const A=RC.agd,p=rcAgdPac(),ags=rcAgdAgendas();
 const linhas=ags.map(a=>{const l=rcLivres(a,A.data),ch=l.filter(rcEhChegada),hr=l.filter(h=>!rcEhChegada(h)),prox=!l.length&&rcProxVaga(a,A.data);return `<tr>${td('Agenda',`<div class="two">${esc(a.nome)}<small>${esc(PROF(a.prof).n)}${a.obs?' · '+esc(a.obs):''}</small></div>`)}${td('Unidade',esc(rcUnidNome(a.unid)))}${td('Data',rcDiaTxt(A.data))}${td('Horários disponíveis',l.length?`<div class="rc-sl">${hr.map(h=>`<button type="button" onclick="rcAgdEscolher('${a.id}','${h}')">${h}</button>`).join('')}${ch.length?`<button type="button" onclick="rcAgdEscolher('${a.id}','${ch[0]}')">Ordem de chegada: ${ch.length} vaga(s)</button>`:''}</div>`:`<span class="tl">Sem vaga neste dia.</span>${prox?` <a href="#" onclick="event.preventDefault();RC.agd.data='${prox}';reView()">Próxima vaga: ${rcDiaTxt(prox)}</a>`:''}`)}</tr>`});
 const qa=semAc(A.q.trim()),feitos=[...RC.ag,...clAgendaHoje().filter(a=>!RC.ag.includes(a.src)).map(a=>({...a,data:RC_HOJE}))].filter(a=>(!p||a.pac===p.n)&&(!qa||semAc(a.pac+' '+(a.cod||'')).includes(qa))).sort((a,b)=>(a.data+a.h).localeCompare(b.data+b.h));RC.agdL=feitos;
 const vg=A.vaga&&RC.agendas.find(x=>x.id===A.vaga.id);const novo=`${A.alt?`<div class="alert info"><span>Alterando <b>${A.alt.cod}</b>: escolha o novo horário.</span><button class="btn sm ghost" onclick="RC.agd.alt=null;reView()">Desistir</button></div>`:''}<div class="card"><h3>1. Paciente</h3>${p?`<div style="margin-top:8px">${kvs([['Nome',esc(p.n)],['CPF',`<span class="mono">${cpfMask(p.cpf)}</span>`],['Nascimento',dmy(p.dn)+' · '+idade(p.dn)+' anos'],['Telefone',esc(p.tel)],['Situação',p.ativo?'Ativo':'Inativo']])}<div class="row"><button class="btn sm ghost" onclick="rcAgdTrocar()">Trocar paciente</button><button class="btn sm ghost" onclick="rcPacEditar('${p.cpf}')">Editar cadastro</button></div></div>`:`${rcPacFiltros('agd','agdFiltro')}<div id="rcAgdLista">${rcAgdPacLista()}</div>`}</div>
 ${vg?`<div class="card" style="margin-top:12px"><h3>2. Horário escolhido na agenda</h3><div style="margin-top:8px">${kvs([['Profissional',esc(PROF(vg.prof).n)],['Agenda',esc(vg.nome)],['Unidade',esc(rcUnidNome(vg.unid))],['Data e hora',`${rcDiaTxt(A.data)} ${rcHoraTxt(A.vaga.h)}`]])}</div><div class="row" style="gap:6px"><button class="btn" ${p?'':'disabled'} onclick="rcAgdEscolher('${vg.id}','${A.vaga.h}')">Confirmar este horário</button><a class="btn ghost" href="#agenda" onclick="RC.agd.vaga=null">Escolher outro na agenda</a></div>${p?'':'<p class="tl" style="margin-top:8px">Localize o paciente para confirmar.</p>'}</div>`:`<div class="card" style="margin-top:12px"><h3>2. Agendas disponíveis</h3>${p?'':'<p class="tl">Localize o paciente para marcar. Os horários já podem ser consultados.</p>'}
 <div class="filters" style="margin-top:8px"><select class="in" style="width:auto" aria-label="Unidade" onchange="RC.agd.unid=this.value;reView()"><option value="">Todas as unidades</option>${rcUnidOpts(A.unid)}</select><select class="in" style="width:auto" aria-label="Profissional" onchange="RC.agd.prof=this.value;reView()"><option value="">Todos os profissionais</option>${rcProfOpts(A.prof)}</select><select class="in" style="width:auto" aria-label="Procedimento" onchange="RC.agd.proc=this.value;reView()"><option value="">Todos os procedimentos</option>${rcOpts(PROCEDIMENTOS.map(x=>[x.c,x.n]),A.proc)}</select><input class="in" type="date" style="width:auto" aria-label="Data" value="${A.data}" min="${RC_HOJE}" onchange="RC.agd.data=this.value||RC_HOJE;reView()"></div>
 ${ags.length?tabela(['Agenda','Unidade','Data','Horários disponíveis'],linhas):`<div class="empty"><h4>Nenhuma agenda aberta com esses filtros</h4><p>Registre o interesse para retomar o contato quando abrir.</p><button class="btn sm sec" onclick="rcPreNovo()">Registrar pré-agendamento</button></div>`}
 ${ags.length?`<p class="tl" style="margin-top:8px">Não achou horário? <a href="#" onclick="event.preventDefault();rcPreNovo()">Registrar pré-agendamento</a></p>`:''}</div>`}`;
 return `${pageHead('Recepção','Agendamento',vg?'Localize o paciente e confirme o horário escolhido.':'Localize o paciente, escolha a agenda e o horário.',`<a class="btn sec" href="#agenda" onclick="RC.agd.vaga=null">Voltar à agenda</a>`)}
 ${rcTabs([['novo','Novo agendamento'],['feitos','Agendamentos realizados',feitos.length]],A.tab,'RC.agd.tab')}<div style="margin-top:12px">${A.tab==='novo'?novo:`<div class="filters"><div class="inwrap" style="flex:1 1 240px">${LUPA}<input class="in" placeholder="Paciente ou código do agendamento" value="${esc(A.q)}" onchange="RC.agd.q=this.value;reView()" aria-label="Buscar agendamento"></div></div>${tabela(['Data','Hora','Paciente','Procedimento','Profissional e unidade','Modalidade','Situação',''],feitos.map((x,i)=>`<tr>${td('Data',rcDiaTxt(x.data))}${td('Hora',x.h)}${td('Paciente',`<div class="two">${esc(x.pac)}<small>${x.cod||''}</small></div>`)}${td('Procedimento',esc(rcProcsTxt(x.itens)))}${td('Profissional e unidade',`<div class="two">${esc((PROF(x.prof)||{n:'Laboratório'}).n)}<small>${esc(rcUnidNome(x.unid||RC.unid))}</small></div>`)}${td('Modalidade',esc(x.conv||'Particular'))}${td('Situação',`<span class="badge ${RC_STATUS[rcStDe(x.sit)]||'neutral'}">${rcAgSit(x.sit)}</span>${x.motivo?`<small style="display:block">${esc(x.motivo)}</small>`:''}`)}${td('',`<div class="row" style="gap:4px;flex-wrap:nowrap">${rcAgAcoes(x,i)}</div>`)}</tr>`),p?'Nenhum agendamento deste paciente':'Nenhum agendamento encontrado')}`}</div>`};
function rcAgAcoes(x,i){const ab=['agendado','confirmado'].includes(x.sit),pode=permAcaoOn(PERFIL,'Agenda','remarcar'),ch=ab&&x.data===RC_HOJE?`<button class="btn sm" onclick="rcAgChegar(${i})">Confirmar chegada</button>`:'';
 if(x.ref)return `${ch}<button class="btn sm ghost" onclick="clAgVer('${x.ref}')">Ver</button>`;
 return ch+(!ab?'':pode?`<button class="btn sm sec" onclick="rcAgAlterar(${i})">Alterar</button><button class="btn sm ghost" onclick="rcAgCancelar(${i})">Cancelar</button>`:'<span class="tl">Sem permissão para alterar</span>')}
function rcAgChegar(i){const x=RC.agdL[i],s=x&&rcChegada(x.src||x);if(s){rcIrSenha(s.num);toast(`Chegada confirmada: senha ${s.num}`)}}
function rcAgAlterar(i){const x=RC.agdL[i];if(!x)return;Object.assign(RC.agd,{cpf:x.cpf,prof:x.prof,proc:x.itens[0],unid:String(x.unid),data:x.data,tab:'novo',alt:x,vaga:null});reView();toast('Escolha o novo horário')}
function rcAgCancelar(i){rcTextoModal('Cancelar agendamento','Motivo',`rcAgCancelarOk(${i})`,'Cancelar agendamento')}
function rcAgCancelarOk(i){const x=RC.agdL[i],m=$('#rcMot').value.trim();if(!m){toast('Informe o motivo','warn');return}rcDesmarcar(x,m);closeModal();reView();toast('Agendamento cancelado: o horário voltou a ficar disponível')}
function rcAgdEscolher(id,h){const A=RC.agd,p=rcAgdPac(),a=RC.agendas.find(x=>x.id===id);if(!p){toast('Selecione o paciente antes do horário','warn');return}
 const procs=rcProcsDoHorario(a,A.data,h).filter(c=>EX[c]),sel=procs.includes(A.proc)?A.proc:procs[0];
 openModal(`${mh('Confirmar agendamento')}<div class="mb">${kvs([['Paciente',`<b>${esc(p.n)}</b>`],['CPF',`<span class="mono">${cpfMask(p.cpf)}</span>`],['Nascimento',dmy(p.dn)],['Telefone',esc(p.tel)],['Agenda',esc(a.nome)],['Profissional',esc(PROF(a.prof).n)],['Unidade',esc(rcUnidNome(a.unid))],['Data e hora',`${rcDiaTxt(A.data)} ${rcHoraTxt(h)}`],...(a.obs?[['Observações da agenda',esc(a.obs)]]:[])])}<div class="field" style="margin-top:8px"><label for="rcAgdProc">Procedimento</label><select class="in" id="rcAgdProc">${rcOpts(procs.map(c=>[c,clProcNome(c)]),sel)}</select></div><div class="field"><label for="rcAgdConv">Convênio ou modalidade</label><select class="in" id="rcAgdConv">${rcOpts(rcModal().map(m=>[m,m]),A.alt?A.alt.conv:'Particular')}</select></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="rcAgdOk('${id}','${h}')">Confirmar agendamento</button></div>`)}
/* Nota 194: a mensagem sai mesmo que o redesenho da tela falhe */
const rcReViewSeguro=()=>{try{reView()}catch(e){console.error(e)}};
const rcAgVerFeitos="RC.agd.vaga=null;RC.agd.tab='feitos';location.hash='#agendamento'";
const rcAgdTxtOk=(r,data,h)=>`${r.ok.cod}: ${esc(r.ok.pac.split(' ')[0])} está marcado para ${rcDiaTxt(data)} ${rcHoraTxt(h)} com ${esc(PROF(r.ok.prof).n)}.`;
function rcAgdOk(id,h){const A=RC.agd,r=rcAgendar({agenda:id,data:A.data,h,cpf:A.cpf,proc:$('#rcAgdProc').value,conv:$('#rcAgdConv').value,alt:A.alt});closeModal();
 if(r.erro){rcReViewSeguro();retorno('erro','Não foi possível agendar',r.erro);return}A.alt=null;
 if(A.pre){const pr=RC.pre.find(x=>x.id===A.pre);if(pr){pr.st='Agendado';pr.log.push('Agendado para '+rcDiaBr(A.data)+' '+rcHoraTxt(h));rcHist(pr,'pre','Pré-agendamento convertido',r.ok.cod,(PROF(pr.prof)||{}).n)}A.pre=null}
 A.vaga=null;A.tab='feitos';rcReViewSeguro();retorno('ok','Agendamento confirmado',rcAgdTxtOk(r,A.data,h))}

/* ---------- Nota 245: agendar numa única janela, sem sair da Agenda ----------
   Horário > paciente > conferir dados > convênio > procedimentos daquele médico naquele convênio > finalizar.
   Convênio e modalidade da agenda: DeoVita = Assinante, Particular = Não assinante, JCC = Coparticipação (dados de exemplo).
   Agendas sem tabela própria (as de exemplo) seguem RC_VJ_TIPOS, também de exemplo. */
const RC_VJ_CONV={DeoVita:'ass',Particular:'nao',JCC:'cop'};
const RC_VJ_TIPOS={DeoVita:['Consulta','Imagem'],Particular:['Consulta','Imagem','Procedimento'],JCC:['Consulta']};
function rcVjProcs(V){const a=RC.agendas.find(x=>x.id===V.agenda);if(!a||!V.conv)return [];const base=rcProcsDoHorario(a,V.data,V.h).filter(c=>EX[c]),m=RC_VJ_CONV[V.conv];
 const l=a.linhas?a.linhas.filter(x=>x.mod===m&&x.c&&base.includes(x.c)).map(x=>({c:x.c,v:x.v})):base.filter(c=>RC_VJ_TIPOS[V.conv].includes((PROC(c)||{}).tipo)).map(c=>({c,v:rcValMod(c,m)}));return l.filter((x,i)=>l.findIndex(y=>y.c===x.c)===i)}
function rcVjAbrir(agenda,data,h){RC.vj={agenda,data,h,etapa:1,q:'',l:[],pac:null,ed:null,conv:'',proc:''};rcVjPinta()}
function rcVjPinta(){const h=rcVjHtml();if(modalAberto())$('#modal').innerHTML=h;else openModal(h,'wide');const i=$('#modal .mb input');if(i)i.focus()}
function rcVjLista(){const V=RC.vj;if(!V.q.trim())return '<p class="tl" style="margin-top:8px">Digite o nome ou o CPF do paciente.</p>';V.l=rcBuscaNomeCpf(V.q).slice(0,8);
 if(!V.l.length)return `<div class="empty" style="padding:14px 8px"><h4>Ninguém encontrado</h4><p>Confira o que digitou ou faça o cadastro para agendar.</p><button class="btn sm sec" onclick="rcVjCadastrar()">Cadastrar paciente</button></div>`;
 return `<div class="at-list" style="margin-top:8px">${V.l.map((p,i)=>`<div class="at-row clk" onclick="rcVjEsc(${i})"><div class="grow"><b>${esc(p.n)}</b><small>CPF <span class="mono">${cpfVer(p.cpf)}</span> · Nascimento ${dmy(p.dn)||'não informado'}</small></div><span class="btn sm sec">Selecionar</span></div>`).join('')}</div>`}
function rcVjCadastrar(){const q=RC.vj.q.trim();sobreModal(()=>rcPacEditar('',{.../[a-zà-ú]/i.test(q)?{n:q}:{cpf:mCPF(q)},vj:true}),'Voltar à busca')}
const rcVjCampoWa=p=>p.wa2&&!p.wa1?'tel2':'tel';
function rcVjEsc(i){const V=RC.vj,p=V.l[i];if(!p)return;V.pac=p;V.ed={n:p.n,cpf:p.cpf,wa:p[rcVjCampoWa(p)]||''};V.etapa=2;rcVjPinta()}
/* Edição rápida: mesmo registro do cadastro (quem e quando, em Histórico) e CPF único */
function rcVjDados(){const V=RC.vj,p=V.pac,v=id=>($('#'+id).value||'').trim(),nome=rcCaixaAlta(v('rcVjN')),cpf=mCPF(v('rcVjC')),wa=v('rcVjW');V.ed={n:v('rcVjN'),cpf,wa};
 if(!nome){toast('Informe o nome','warn');return}if(soDig(cpf).length!==11){toast('CPF precisa de 11 números','warn');return}if(PACIENTES.some(x=>x!==p&&soDig(x.cpf)===soDig(cpf))){toast('Já existe outro cadastro com este CPF','warn');return}if(soDig(wa).length<10){toast('Informe o WhatsApp com DDD','warn');return}
 const k=rcVjCampoWa(p),n=rcCaixaAlta(p.n)===nome?p.n:nome,campos=[n!==p.n&&'Nome',cpf!==p.cpf&&'CPF',wa!==(p[k]||'')&&'WhatsApp'].filter(Boolean);
 if(campos.length){const an=p.n,ac=p.cpf;p.n=n;p.cpf=cpf;p[k]=wa;if(k==='tel')p.wa1=true;rcPacPropaga(an,ac,n,cpf);rcHist(p,'recepcao','Cadastro atualizado',`Edição rápida na janela de agendamento: ${campos.join(', ')}${cpf!==ac&&ac?`. CPF anterior ${cpfMask(ac)}`:''}`);toast('Cadastro atualizado')}
 V.etapa=3;rcVjPinta()}
/* Quem mudou de nome ou CPF continua ligado às próprias senhas, guias, agendamentos e histórico */
function rcPacPropaga(an,ac,n,cpf){const troca=x=>{if(x.cpf&&ac&&x.cpf!==ac)return;if(x.pac===an)x.pac=n;if(ac&&x.cpf===ac)x.cpf=cpf};[RC.senhas,RC.ag,RC.at,RC.guias,RC.pre,RC.hist,AG_CLIN,CL_AG_EXTRA,CL_AG_NOVOS].forEach(l=>l.forEach(troca));[...ATENDS,...FILA.rec,...FILA.col].forEach(a=>{if(a.n===an)a.n=n});if(ac){if(RC.agd.cpf===ac)RC.agd.cpf=cpf;if(RC.pa.cpf===ac)RC.pa.cpf=cpf}}
function rcVjConv(c){const V=RC.vj;V.conv=c;const l=rcVjProcs(V);V.proc=l.some(x=>x.c===V.proc)?V.proc:l.length===1?l[0].c:'';rcVjPinta()}
function rcVjProc(c){RC.vj.proc=c;$('#rcVjFim').disabled=false}
function rcVjFinalizar(){const V=RC.vj,r=rcAgendar({agenda:V.agenda,data:V.data,h:V.h,cpf:V.pac.cpf,proc:V.proc,conv:V.conv});closeModal();rcReViewSeguro();
 if(r.erro){retorno('erro','Não foi possível agendar',r.erro);return}RC.vj=null;retorno('ok','Agendamento confirmado',rcAgdTxtOk(r,r.ok.data,r.ok.h),[{l:'Entendi'},{l:'Ver agendamentos realizados',sec:true,on:rcAgVerFeitos}])}
function rcVjHtml(){const V=RC.vj,a=RC.agendas.find(x=>x.id===V.agenda),m=PROF(a.prof),pas=['Paciente','Conferir dados','Convênio e procedimento'],p=V.pac,E=V.ed;
 const topo=`<div class="rc-vj-p">${pas.map((t,i)=>`<span class="${V.etapa===i+1?'on':V.etapa>i+1?'ok':''}">${i+1}. ${t}</span>`).join('')}</div><div class="rc-vj-res"><b>${esc(m.n)}</b> · ${esc(m.esp)} · <b>${rcDiaTxt(V.data)} ${rcHoraTxt(V.h)}</b> · ${esc(rcUnidNome(a.unid))}${V.etapa>2?` · ${esc(p.n)}`:''}</div>`;
 let corpo,rod;
 if(V.etapa===1){corpo=`<div class="inwrap">${LUPA}<input class="in" id="rcVjQ" placeholder="Pesquise pelo nome ou CPF do paciente" aria-label="Pesquisar paciente por nome ou CPF" value="${esc(V.q)}" oninput="RC.vj.q=this.value;$('#rcVjRes').innerHTML=rcVjLista()"></div><div id="rcVjRes">${rcVjLista()}</div>`;rod=`<button class="btn ghost" onclick="closeModal()">Cancelar</button>`}
 else if(V.etapa===2){corpo=`<div class="pf-g"><div class="field s6"><label for="rcVjN">Nome do paciente <span class="req">*</span></label><input class="in cx" id="rcVjN" value="${esc(E.n)}"></div><div class="field s3"><label for="rcVjC">CPF <span class="req">*</span></label><input class="in" id="rcVjC" value="${esc(E.cpf)}" oninput="this.value=mCPF(this.value)"></div><div class="field s3"><label for="rcVjW">WhatsApp <span class="req">*</span></label><input class="in" id="rcVjW" value="${esc(E.wa)}" oninput="this.value=mTel(this.value)"></div></div><p class="tl" style="margin:8px 0 0">Nascimento: ${dmy(p.dn)||'não informado'}. Confira o WhatsApp: é por ele que o paciente confirma o atendimento.</p>`;rod=`<button class="btn ghost" onclick="RC.vj.etapa=1;rcVjPinta()">Voltar</button><button class="btn" onclick="rcVjDados()">Continuar</button>`}
 else{const l=rcVjProcs(V);corpo=`<h4 style="margin:0 0 6px"><label for="rcVjConvC">Convênio <span class="req">*</span></label></h4>${cbHtml({id:'rcVjConvC',val:V.conv,ph:'Selecione ou digite o convênio',min:1,fn:'rcVjConv',itens:Object.keys(RC_VJ_CONV).map(c=>({v:c,t:c}))})}<h4 style="margin:14px 0 6px">Procedimentos</h4>${!V.conv?'<p class="tl" style="margin:0">Selecione o convênio para ver os procedimentos deste médico.</p>':!l.length?`<div class="empty" style="padding:14px 8px"><h4>Sem procedimentos</h4><p>${esc(m.n)} não tem procedimento neste horário por ${V.conv}.</p></div>`:`<div class="at-list">${l.map(x=>`<label class="at-row check"><input type="radio" name="rcVjP" ${V.proc===x.c?'checked':''} onchange="rcVjProc('${x.c}')"><div class="grow">${esc(clProcNome(x.c))}<small>R$ ${rcMoeda(x.v)}</small></div></label>`).join('')}</div>`}`;rod=`<button class="btn ghost" onclick="RC.vj.etapa=2;RC.vj.ed={n:RC.vj.pac.n,cpf:RC.vj.pac.cpf,wa:RC.vj.pac[rcVjCampoWa(RC.vj.pac)]||''};rcVjPinta()">Voltar</button><button class="btn" id="rcVjFim" ${V.proc?'':'disabled'} onclick="rcVjFinalizar()">Finalizar agendamento</button>`}
 const obs=rcObsVaga(a,V.data,V.h);return `${mh('Novo agendamento')}<div class="mb">${topo}${obs?`<div class="alert warn rc-vj-obs"><div><b>Observações da agenda:</b> ${esc(obs)}</div></div>`:''}${corpo}</div><div class="mf">${rod}</div>`}

/* ---------- Agenda do médico: mensal e diária (notas 78, 79, 81 a 89) ---------- */
function rcMesHtml(){const C=RC.ca,prim=new Date(C.ano,C.mes,1),n=new Date(C.ano,C.mes+1,0).getDate(),cel=[];for(let i=0;i<prim.getDay();i++)cel.push('<div></div>');
 for(let d=1;d<=n;d++){const k=iso(new Date(C.ano,C.mes,d)),v=rcVagasProf(C.prof,k,RC.unid),liv=v.filter(x=>x.st==='VAGA DISPONÍVEL').length,mar=v.filter(x=>RC_STATUS[x.st]&&!x.st.startsWith('VAGA')).length;
  cel.push(`<button type="button" class="rc-d ${v.length?(liv?'on':'cheio'):''} ${k===RC_HOJE?'hj':''}" onclick="RC.ca.dia='${k}';RC.ca.modo='dia';RC.ca.st='';reView()" aria-label="${d} de ${RC_MESES[C.mes]}"><b>${d}</b><small>${v.length?`${mar} marcados · ${liv} vagas`:''}</small></button>`)}
 return `<div class="rc-mes" style="margin-bottom:6px">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=>`<span>${x}</span>`).join('')}</div><div class="rc-mes">${cel.join('')}</div><div class="cl-leg" style="margin-top:10px"><span><i style="background:var(--accent-soft);border:1px solid var(--accent)"></i>Agenda aberta com vaga</span><span><i style="background:var(--warn-soft);border:1px solid var(--warn)"></i>Agenda aberta sem vaga</span><span><i style="background:var(--surface);border:1px solid var(--border)"></i>Sem agenda</span></div>`}
/* Notas 263, 266 a 271: resumo clicável, Confirmado como única situação manual e coluna Ações por situação. */
const rcObsVaga=(a,d,h)=>a?(rcPerDoHorario(a,d,h)||{}).obs||a.obs||'':'';
const rcAgendaDaVaga=(h)=>{const C=RC.ca;return RC.agendas.find(a=>a.prof===C.prof&&a.unid===RC.unid&&rcDiaAberto(a,C.dia)&&rcSlots(a,C.dia).includes(h))};
const RC_RESUMO=[['','Todos','tod'],['AGENDADO','Agendados','ag'],['CONFIRMADO','Confirmados','co'],['VAGA DISPONÍVEL','Disponíveis','di'],['VAGA BLOQUEADA','Bloqueados','bl'],['FINALIZADO','Finalizados','fi']];
const rcCadeado=a=>`<svg class="i" viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="${a?'M8 11V7a4 4 0 0 1 7.5-2':'M8 11V7a4 4 0 0 1 8 0v4'}"/></svg>`;
const rcDiaLivres=()=>{const C=RC.ca;return rcVagasProf(C.prof,C.dia,RC.unid).filter(v=>v.st==='VAGA DISPONÍVEL')};
function rcDiaAcao(i,v){const x=RC.diaL[i];if(!x)return;const C=RC.ca;
 if(v==='BLOQ'){RC.bloq.add(rcBk(C.prof,C.dia,x.h));toast('Vaga bloqueada')}else if(v==='LIB'){RC.bloq.delete(rcBk(C.prof,C.dia,x.h));toast('Vaga liberada')}
 else if(v==='AG'){const ag=rcAgendaDaVaga(x.h);if(ag)rcVjAbrir(ag.id,C.dia,x.h);else toast('Este horário não pertence a uma agenda aberta nesta unidade','warn');return}
 reView()}
function rcDiaConfirmarModal(i){const x=RC.diaL[i];if(!x||x.st!=='AGENDADO')return;modalOk('Confirmar agendamento',`<p><b>${esc(x.ev.pac)}</b> confirmou o horário das <b>${x.h}</b> pelo WhatsApp?</p>`,'Marcar como confirmado',`rcDiaConfirmar(${i})`)}
function rcDiaConfirmar(i){const x=RC.diaL[i];if(!x||x.st!=='AGENDADO')return;(x.ev.src||x.ev).sit='confirmado';rcHist(x.ev,'agenda','Agendamento: Confirmado',x.h+' · paciente confirmou pelo WhatsApp',PROF(RC.ca.prof).n);reView();toast('Situação: CONFIRMADO')}
function rcDiaCancelar(i){const x=RC.diaL[i];if(x)rcTextoModal('Cancelar agendamento de '+esc(x.ev.pac)+' às '+x.h,'Motivo',`rcDiaCancelarOk(${i})`,'Cancelar agendamento')}
function rcDiaCancelarOk(i){const x=RC.diaL[i],m=$('#rcMot').value.trim();if(!m){toast('Informe o motivo','warn');return}rcDesmarcar(x.ev.src||x.ev,m);closeModal();reView();toast('Agendamento cancelado e horário liberado')}
function rcDiaWhats(i){const x=RC.diaL[i];if(!x)return;const p=PACIENTES.find(y=>y.n===x.ev.pac)||{},t=p[rcVjCampoWa(p)]||p.tel||'';rcHist(x.ev,'agenda','Contato pelo WhatsApp',x.h,PROF(RC.ca.prof).n);toast(t?`No sistema real, abre a conversa com ${x.ev.pac} em ${t}`:'Paciente sem telefone cadastrado',t?'ok':'warn')}
function rcDiaBloqTodosModal(){const n=rcDiaLivres().length;if(!n){toast('Não há vaga disponível nesta data','warn');return}modalOk('Bloquear todas as vagas disponíveis?',`<p><b>${n}</b> vaga(s) de <b>${rcDiaLongo(RC.ca.dia)}</b> ficam bloqueadas. Quem já está agendado não muda.</p>`,'Bloquear todas','rcDiaBloqTodos()','danger')}
