function rcDiaCelAcoes(v,i){const wrap=h=>`<div class="rc-ac">${h}</div>`;if(v.st==='FINALIZADO')return '';
 if(v.ev)return wrap(`<button type="button" class="btn sm wa rc-ic" title="Abrir conversa no WhatsApp" aria-label="Abrir conversa no WhatsApp" onclick="rcDiaWhats(${i})"><span class="wa-ic"><i class="fa-brands fa-whatsapp"></i></span></button><button type="button" class="btn sm danger sec rc-ic" title="Cancelar agendamento" aria-label="Cancelar agendamento" onclick="rcDiaCancelar(${i})">${I.x}</button>`);
 return wrap(v.st==='VAGA DISPONÍVEL'?`<button type="button" class="btn sm ghost" title="Bloquear este horário" onclick="rcDiaAcao(${i},'BLOQ')">${rcCadeado()} Bloquear</button>`:`<button type="button" class="btn sm ghost" title="Desbloquear este horário" onclick="rcDiaAcao(${i},'LIB')">${rcCadeado(1)} Desbloquear</button>`)}
function rcDiaHtml(){const C=RC.ca,todos=rcVagasProf(C.prof,C.dia,RC.unid),l=todos.filter(v=>!C.st||v.st===C.st);RC.diaL=l;
 const aberta=RC.agendas.some(a=>a.prof===C.prof&&a.unid===RC.unid&&rcDiaAberto(a,C.dia)),livres=todos.filter(v=>v.st==='VAGA DISPONÍVEL').length;
 const resumo=`<div class="rc-res" role="group" aria-label="Resumo da agenda">${RC_RESUMO.map(([k,t,c])=>`<button type="button" class="rc-res-c rc-c-${c} ${(C.st||'')===k?'on':''}" aria-pressed="${(C.st||'')===k}" onclick="RC.ca.st='${k}';reView()"><b>${k?todos.filter(v=>v.st===k).length:todos.length}</b><span>${t}</span></button>`).join('')}</div>`;
 const acoes=`<span class="rc-th-ac">AÇÕES${livres?`<button type="button" class="btn sm ghost" title="Bloquear todas as vagas disponíveis nesta data" onclick="rcDiaBloqTodosModal()">${rcCadeado()} Bloquear todas</button>`:''}</span>`;
 const sit=(v,i)=>v.st==='AGENDADO'?`<button type="button" class="badge info rc-sit-bt" title="Clique para marcar como confirmado" onclick="rcDiaConfirmarModal(${i})">AGENDADO</button>`:`<span class="badge ${RC_STATUS[v.st]}">${v.st}</span>`;
 const paciente=v=>{if(v.ev)return v.ev.ref?`<a href="#" onclick="event.preventDefault();clAgVer('${v.ev.ref}')">${esc(v.ev.pac)}</a>`:esc(v.ev.pac);if(v.st!=='VAGA DISPONÍVEL')return '<span class="tl">Bloqueado</span>';const o=rcObsVaga(rcAgendaDaVaga(v.h),C.dia,v.h);return `<div class="two"><span class="tl">Livre</span>${o?`<small class="rc-obs">${esc(o)}</small>`:''}</div>`};
 return `${resumo}
 ${!todos.length?`<div class="empty"><h4>${aberta?'Sem horários':'Sem agenda aberta neste dia'}</h4><p>Abra a agenda ou escolha outro dia.</p><a class="btn sm sec" href="#abertura-agenda">Abertura de agenda</a></div>`:tabela(['Hora','Paciente','Procedimento','Situação',acoes],l.map((v,i)=>`<tr ${!v.ev&&v.st==='VAGA DISPONÍVEL'?`style="cursor:pointer" onclick="if(!event.target.closest('button'))rcDiaAcao(${i},'AG')"`:''}>${td('Hora',`<b>${v.h}</b>`)}${td('Paciente',paciente(v))}${td('Procedimento',v.ev?esc(v.ev.itens.map(clProcNome).join(', ')):'')}${td('Situação',sit(v,i))}${td('Ações',rcDiaCelAcoes(v,i))}</tr>`),'Nenhum horário com esta situação')}`}
/* Nota 213: duas pesquisas independentes; a escolhida carrega a agenda sem botão */
const rcEspDe=p=>p.esp.split(' (')[0];
const rcEspsLista=()=>[...new Set(PROFISSIONAIS.filter(p=>p.ativo).map(rcEspDe).concat(RC.agendas.flatMap(a=>a.esps||[])))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
const rcProfsEsp=e=>PROFISSIONAIS.filter(p=>p.ativo&&(rcEspDe(p)===e||RC.agendas.some(a=>a.prof===p.id&&(a.esps||[]).includes(e)))).sort((a,b)=>a.n.localeCompare(b.n,'pt-BR'));
function rcCaBusca(m){const C=RC.ca;C.busca=m;if(m==='esp')C.prof='';else C.esp='';reView()}
function rcCaProf(t){const C=RC.ca,q=semAc(String(t).trim()),med=PROFISSIONAIS.filter(p=>p.ativo);if(!q){C.prof='';reView();return}const ex=med.find(p=>semAc(p.n+' · '+p.esp)===q||semAc(p.n)===q),l=ex?[ex]:med.filter(p=>semAc(p.n+' '+p.esp).includes(q));if(l.length!==1){toast(l.length?'Mais de um profissional encontrado: escolha na lista':'Nenhum profissional encontrado','warn');return}C.prof=l[0].id;C.esp='';C.modo='mes';reView()}
function rcCaEsp(t){const C=RC.ca,q=semAc(String(t).trim()),es=rcEspsLista();if(!q){C.esp='';reView();return}const ex=es.find(e=>semAc(e)===q),ini=es.filter(e=>semAc(e).startsWith(q)),l=ex?[ex]:ini.length===1?ini:es.filter(e=>semAc(e).includes(q));if(l.length!==1){toast(l.length?'Mais de uma especialidade encontrada: escolha na lista':'Nenhuma especialidade encontrada','warn');return}C.esp=l[0];C.prof='';reView()}
function rcCaMover(n){if(RC.ca.prof&&RC.ca.modo==='dia')rcDiaMover(n);else rcMesMover(n)}
function rcCaHoje(){const C=RC.ca;C.ano=+RC_HOJE.slice(0,4);C.mes=+RC_HOJE.slice(5,7)-1;if(C.modo==='dia')C.dia=RC_HOJE;reView()}
/* Visão conjunta da especialidade: datas em ordem, com o profissional identificado em cada linha */
function rcEspHtml(){const C=RC.ca,n=new Date(C.ano,C.mes+1,0).getDate(),profs=rcProfsEsp(C.esp),ls=[];
 for(let d=1;d<=n;d++){const k=iso(new Date(C.ano,C.mes,d));if(k<RC_HOJE)continue;profs.forEach(p=>RC.agendas.filter(a=>a.prof===p.id&&a.unid===RC.unid&&rcDiaAberto(a,k)).forEach(a=>{const c=a.datas?a.datas[k]:a,l=rcLivres(a,k),ch=l.filter(rcEhChegada),hr=l.filter(h=>!rcEhChegada(h)),fx=(c.periodos||[c]).map(x=>(x.modo||c.modo)==='chegada'?'a partir das '+x.ini:x.ini+' às '+x.fim).sort().join(' e ');
  ls.push(`<tr>${td('Data',`<b>${rcDiaTxt(k)}</b>`)}${td('Profissional',`<div class="two"><a href="#" onclick="event.preventDefault();RC.ca.prof='${p.id}';RC.ca.esp='';RC.ca.busca='prof';RC.ca.dia='${k}';RC.ca.modo='dia';reView()">${esc(p.n)}</a><small>${esc(p.esp)}</small></div>`)}${td('Atendimento',esc(fx))}${td('Horários livres',l.length?`<div class="rc-sl">${hr.map(h=>`<button type="button" onclick="rcVjAbrir('${a.id}','${k}','${h}')">${h}</button>`).join('')}${ch.length?`<button type="button" onclick="rcVjAbrir('${a.id}','${k}','${ch[0]}')">Ordem de chegada: ${ch.length} vaga(s)</button>`:''}</div>`:'<span class="tl">Sem vaga</span>')}</tr>`)}))}
 return ls.length?tabela(['Data','Profissional','Atendimento','Horários livres'],ls):`<div class="empty"><h4>Nenhuma agenda aberta em ${RC_MESES[C.mes]}</h4><p>${esc(C.esp)}: ${profs.length} profissional(is) nesta especialidade. Veja o próximo mês.</p></div>`}
/* Notas 256, 261 e 262: lista com pesquisa. min = letras a partir das quais filtra; abaixo disso mostra tudo. */
const CB={};
function cbHtml({id,val,ph,itens,min,fn,icone}){const atual=itens.find(x=>x.v===val);CB[id]={itens,min:min||1,fn,icone,txt:atual?atual.t:'',aceso:-1};return `<div class="cb"><input class="in" id="${id}" role="combobox" aria-expanded="false" aria-controls="${id}_l" aria-autocomplete="list" autocomplete="off" placeholder="${esc(ph)}" value="${esc(CB[id].txt)}" onclick="cbAbre('${id}')" oninput="cbAbre('${id}')" onkeydown="cbTecla(event,'${id}')" onblur="setTimeout(()=>cbFecha('${id}'),120)"><svg class="i cb-seta" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg><div class="cb-lista" id="${id}_l" role="listbox" hidden onmousedown="event.preventDefault()"></div></div>`}
function cbVisiveis(id){const c=CB[id],t=$('#'+id).value.trim(),q=semAc(t);c.l=t===c.txt||q.length<c.min?c.itens:c.itens.filter(x=>semAc(x.t+' '+(x.s||'')).includes(q));return c.l}
function cbAbre(id){const c=CB[id],l=cbVisiveis(id),b=$('#'+id+'_l');c.aceso=-1;b.innerHTML=l.length?l.map((x,i)=>`<button type="button" class="cb-op" role="option" onclick="cbEscolhe('${id}',${i})">${c.icone?`<span class="cb-ic">${c.icone}</span>`:''}<span class="cb-t"><b>${esc(x.nome||x.t)}</b>${x.s?`<small>${esc(x.s)}</small>`:''}</span></button>`).join(''):'<p class="tl cb-vazio">Nada encontrado</p>';b.hidden=false;$('#'+id).setAttribute('aria-expanded','true')}
function cbFecha(id){const i=document.getElementById(id),b=document.getElementById(id+'_l'),c=CB[id];if(!i||!b||!c||b.hidden)return;b.hidden=true;i.setAttribute('aria-expanded','false');if(document.activeElement===i)return;if(!i.value.trim()&&c.txt){window[c.fn]('');return}i.value=c.txt}
function cbEscolhe(id,k){const c=CB[id],x=c.l[k];if(!x)return;$('#'+id+'_l').hidden=true;c.txt=x.t;$('#'+id).value=x.t;window[c.fn](x.v)}
function cbTecla(e,id){const c=CB[id],b=$('#'+id+'_l');if(e.key==='Escape'){b.hidden=true;return}if(e.key==='Enter'){e.preventDefault();if(!b.hidden&&c.aceso>=0)cbEscolhe(id,c.aceso);else if(!b.hidden&&c.l.length===1)cbEscolhe(id,0);return}if(e.key!=='ArrowDown'&&e.key!=='ArrowUp')return;e.preventDefault();if(b.hidden){cbAbre(id);return}const n=c.l.length;if(!n)return;c.aceso=e.key==='ArrowDown'?(c.aceso+1)%n:(c.aceso<=0?n:c.aceso)-1;[...b.children].forEach((x,i)=>{x.classList.toggle('on',i===c.aceso);if(i===c.aceso)x.scrollIntoView({block:'nearest'})})}
const rcNomeOrdem=p=>p.n.replace(/^[A-ZÀ-Ú]{2,4}\.\s*/,'');
const CB_ICONE='<svg class="i" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></svg>';
