/* ---------- Troca de unidade sem novo login (nota 80) ---------- */
function rcUnidHead(){const el=document.getElementById('unidAtual');if(el){const t=el.querySelector('span');if(t)t.textContent=rcUnidNome(RC.unid)}}
function rcTrocarUnidade(){rc();openModal(`${mh('Trocar de unidade')}<div class="mb"><div class="at-list">${Object.keys(UNIDS).map(u=>`<label class="at-row check"><input type="radio" name="rcUn" value="${u}" ${+u===RC.unid?'checked':''}><div class="grow">${esc(rcUnidNome(u))}${+u===RC.unid?'<small>Unidade atual</small>':''}</div></label>`).join('')}</div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="rcDefUnidade(+document.querySelector('input[name=rcUn]:checked').value)">Trocar</button></div>`)}
function rcDefUnidade(u){RC.unid=u;RC.painel.unid=u;RC.meuG=(rcGuiches().find(g=>g.ativo)||{}).id||'';rcUnidHead();closeModal();reView();toast('Agora em '+rcUnidNome(u))}
const rcUnidLinha=()=>{rc();return `<p style="color:var(--fg2);margin-top:4px">${esc(rcUnidNome(RC.unid))} · <a href="#" onclick="event.preventDefault();rcTrocarUnidade()">trocar de unidade</a></p>`};

